/bin/bash -lc "PYTHONPATH=/opt/or-deps python - <<'PY'
import csv, math, itertools
from collections import defaultdict
base='/app/data'
tech=[]
with open(base+'/technicians.csv', newline='') as f:
    for r in csv.DictReader(f):
        r['bucket_truck']=int(r['bucket_truck']); r['seniority']=int(r['seniority']); r['shift_start']=int(r['shift_start']); r['shift_end']=int(r['shift_end']); r['overtime_limit']=int(r['overtime_limit']);
        r['wage_per_min']=float(r['wage_per_min']); r['overtime_cost_per_min']=float(r['overtime_cost_per_min'])
        for p in ['part_ont','part_radio','part_battery','part_router']:
            r[p]=int(r[p])
        skills={}
        for item in r['skills'].split('|'):
            s,l=item.split(':'); skills[s]=int(l)
        r['skills_map']=skills
        tech.append(r)
byid={t['technician_id']:t for t in tech}
with open(base+'/tickets.csv', newline='') as f:
    tickets=list(csv.DictReader(f))
for tk in tickets:
    for k in ['two_technician_required','bucket_required','release_minute','due_minute','deadline_minute','base_service_minutes','part_ont','part_radio','part_battery','part_router']:
        tk[k]=int(tk[k])
    for k in ['late_penalty_per_min','deferral_penalty','change_penalty']:
        tk[k]=float(tk[k])
for tk in tickets:
    opts=[]
    for p in tech:
        lvl=p['skills_map'].get(tk['required_skill'],0)
        if lvl<=0: continue
        dur=math.ceil(tk['base_service_minutes'] * {1:1.28,2:1.0,3:0.83}[lvl])
        if tk['two_technician_required']:
            for a in tech:
                if a['technician_id']==p['technician_id']: continue
                ok=True
                if tk['bucket_required'] and not (p['bucket_truck'] or a['bucket_truck']): ok=False
                sec=tk['secondary_skill']
                if sec and not (p['skills_map'].get(sec,0)>0 or a['skills_map'].get(sec,0)>0): ok=False
                if tk['risk_class']=='high' and max(p['seniority'], a['seniority'])<3: ok=False
                if ok: opts.append((p['technician_id'], a['technician_id'], dur))
        else:
            ok=True
            if tk['bucket_required'] and not p['bucket_truck']: ok=False
            sec=tk['secondary_skill']
            if sec and not (p['skills_map'].get(sec,0)>0): ok=False
            if ok: opts.append((p['technician_id'], '', dur))
    print(tk['ticket_id'], tk['priority'], tk['required_skill'], 'opts', len(opts), 'sample', opts[:8])
PY"

